uint32_t index = 0;
uint32_t skip = 1;
uint32_t value = *off;

while (value != 0) {
    if ((value & 1) == 0) {
        *off -= skip;
        index++;
    }
    value >>= 1;
    skip <<= 1;
}

return index;

